 (C, "Art. VI, Sec. 2", "How many Senators make up the Senate under the 1987 Constitution?", "24", [("12", "GI-NEIGHBOR-NUMBER"), ("25", "GI-NEIGHBOR-NUMBER"), ("30", "GI-NEIGHBOR-NUMBER")], "The Senate shall be composed of twenty-four Senators", "The Senate has 24 members elected at large."),
 (C, "Art. VI, Sec. 6", "What is the minimum age to be a Member of the House of Representatives?", "25 years old", [("21 years old", "GI-NEIGHBOR-NUMBER"), ("35 years old", "GI-NEIGHBOR-NUMBER"), ("30 years old", "GI-NEIGHBOR-NUMBER")], "at least twenty-five years of age", "A House Member must be at least 25 on election day."),
 (C, "Art. VI, Sec. 7", "How long is the term of a Member of the House of Representatives?", "3 years", [("6 years", "GI-NEIGHBOR-NUMBER"), ("4 years", "GI-NEIGHBOR-NUMBER"), ("2 years", "GI-NEIGHBOR-NUMBER")], "shall be elected for a term of three years", "House Members serve 3-year terms."),
 (C, "Art. VI, Sec. 7", "How many consecutive terms may a Member of the House of Representatives serve?", "Three", [("Two", "GI-NEIGHBOR-NUMBER"), ("Four", "GI-NEIGHBOR-NUMBER"), ("One", "GI-NEIGHBOR-NUMBER")], "No member of the House of Representatives shall serve for more than three consecutive terms", "A House Member may serve up to three terms in a row."),
 (C, "Art. VI, Sec. 5(2)", "Party-list representatives make up what share of the total House membership?", "20 percent", [("10 percent", "GI-NEIGHBOR-NUMBER"), ("25 percent", "GI-NEIGHBOR-NUMBER"), ("50 percent", "GI-NEIGHBOR-NUMBER")], "twenty per centum of the total number of representatives", "Party-list members are 20% of the House."),
 (C, "Art. VI, Sec. 24", "Under the 1987 Constitution, appropriation, revenue and tariff bills must originate exclusively in which body?", "House of Representatives", [("Senate", "GI-WRONG-BODY"), ("Office of the President", "GI-WRONG-BODY"), ("Commission on Audit", "GI-WRONG-BODY")], "shall originate exclusively in the House of Representatives", "Money bills start in the House; the Senate may propose amendments."),
 (C, "Art. VI, Sec. 1", "In whom is legislative power vested under the 1987 Constitution?", "The Congress of the Philippines", [("The President", "GI-WRONG-BODY"), ("The Supreme Court", "GI-WRONG-BODY"), ("The Commission on Elections", "GI-WRONG-BODY")], "The legislative power shall be vested in the Congress of the Philippines", "Congress (Senate and House) holds legislative power."),
 (C, "Art. VII, Sec. 1", "In whom is executive power vested under the 1987 Constitution?", "The President", [("The Vice-President", "GI-WRONG-BODY"), ("The Cabinet", "GI-WRONG-BODY"), ("The Senate President", "GI-WRONG-BODY")], "The executive power shall be vested in the President of the Philippines", "Executive power belongs to the President."),
 (C, "Art. VIII, Sec. 1", "In whom is judicial power vested under the 1987 Constitution?", "One Supreme Court and such lower courts as may be established by law", [("The Department of Justice", "GI-WRONG-BODY"), ("The Ombudsman", "GI-WRONG-BODY"), ("The Congress", "GI-WRONG-BODY")], "The judicial power shall be vested in one Supreme Court and in such lower courts as may be established by law", "Judicial power is with the Supreme Court and the lower courts."),
 (C, "Art. VII, Sec. 2", "What is the minimum age to be elected President of the Philippines?", "40 years old", [("35 years old", "GI-NEIGHBOR-NUMBER"), ("45 years old", "GI-NEIGHBOR-NUMBER"), ("50 years old", "GI-NEIGHBOR-NUMBER")], "at least forty years of age on the day of the election", "The President must be at least 40 on election day."),
 (C, "Art. VII, Sec. 2", "How many years must a person have lived in the Philippines immediately before the election to be President?", "10 years", [("5 years", "GI-NEIGHBOR-NUMBER"), ("2 years", "GI-NEIGHBOR-NUMBER"), ("15 years", "GI-NEIGHBOR-NUMBER")], "a resident of the Philippines for at least ten years immediately preceding such election", "Ten years of residence is required."),
 (C, "Art. VII, Sec. 4", "How long is the term of the President under the 1987 Constitution?", "6 years, with no re-election", [("4 years, with one re-election", "GI-OLD-RULE"), ("6 years, with one re-election", "GI-SOUNDS-RIGHT"), ("3 years, with re-election", "GI-NEIGHBOR-NUMBER")], "The President shall not be eligible for any re-election", "One 6-year term; the President cannot be re-elected."),
 (C, "Art. VII, Sec. 4", "How many successive terms may the Vice-President serve?", "Two", [("One", "GI-NEIGHBOR-NUMBER"), ("Three", "GI-NEIGHBOR-NUMBER"), ("No limit", "GI-SOUNDS-RIGHT")], "No Vice-President shall serve for more than two successive terms", "The Vice-President is limited to two successive terms."),
 (C, "Art. VII, Sec. 18", "Under the 1987 Constitution, a proclamation of martial law may not last longer than how many days without extension by Congress?", "60 days", [("30 days", "GI-NEIGHBOR-NUMBER"), ("90 days", "GI-NEIGHBOR-NUMBER"), ("15 days", "GI-NEIGHBOR-NUMBER")], "for a period not exceeding sixty days", "Martial law is limited to 60 days unless Congress extends it."),
 (C, "Art. VII, Sec. 18", "Within how many hours after a proclamation of martial law must the President report to Congress?", "48 hours", [("24 hours", "GI-NEIGHBOR-NUMBER"), ("72 hours", "GI-NEIGHBOR-NUMBER"), ("7 days", "GI-NEIGHBOR-NUMBER")], "Within forty-eight hours from the proclamation of martial law", "The report to Congress is due within 48 hours."),
 (C, "Art. VIII, Sec. 4(1)", "How many members make up the Supreme Court, counting the Chief Justice?", "15", [("13", "GI-NEIGHBOR-NUMBER"), ("11", "GI-NEIGHBOR-NUMBER"), ("9", "GI-NEIGHBOR-NUMBER")], "a Chief Justice and fourteen Associate Justices", "One Chief Justice plus 14 Associate Justices."),
 (C, "Art. VIII, Sec. 11", "Up to what age may members of the Supreme Court hold office?", "70 years", [("65 years", "GI-NEIGHBOR-NUMBER"), ("60 years", "GI-NEIGHBOR-NUMBER"), ("75 years", "GI-NEIGHBOR-NUMBER")], "until they reach the age of seventy years", "Justices serve until age 70."),
 (C, "Art. VIII, Sec. 7(1)", "What is the minimum age to be appointed a member of the Supreme Court?", "40 years old", [("35 years old", "GI-NEIGHBOR-NUMBER"), ("45 years old", "GI-NEIGHBOR-NUMBER"), ("50 years old", "GI-NEIGHBOR-NUMBER")], "must be at least forty years of age", "A Justice must be at least 40."),
 (C, "Art. VIII, Sec. 8(1)", "Which body recommends appointees to the Judiciary under the 1987 Constitution?", "Judicial and Bar Council", [("Integrated Bar of the Philippines", "GI-SIBLING-TERM"), ("Commission on Appointments", "GI-SIBLING-TERM"), ("Department of Justice", "GI-WRONG-BODY")], "A Judicial and Bar Council is hereby created", "The JBC screens and recommends nominees to the courts."),
 (C, "Art. IX-B, Sec. 1(1)", "How many Commissioners does the Civil Service Commission have, besides its Chairman?", "Two", [("Three", "GI-NEIGHBOR-NUMBER"), ("Four", "GI-NEIGHBOR-NUMBER"), ("Six", "GI-NEIGHBOR-NUMBER")], "composed of a Chairman and two Commissioners", "The CSC has a Chairman and two Commissioners."),
 (C, "Art. IX-B, Sec. 1(1)", "What is the minimum age to be appointed Chairman or Commissioner of the Civil Service Commission?", "35 years old", [("40 years old", "GI-NEIGHBOR-NUMBER"), ("30 years old", "GI-NEIGHBOR-NUMBER"), ("45 years old", "GI-NEIGHBOR-NUMBER")], "at least thirty-five years of age", "CSC members must be at least 35 when appointed."),
 (C, "Art. IX-B, Sec. 1(2)", "How long is the term of the Chairman of the Civil Service Commission?", "7 years, without reappointment", [("6 years, with one reappointment", "GI-SOUNDS-RIGHT"), ("5 years, without reappointment", "GI-NEIGHBOR-NUMBER"), ("9 years, without reappointment", "GI-NEIGHBOR-NUMBER")], "for a term of seven years without reappointment", "CSC Chairman: one 7-year term, no reappointment."),
 (C, "Art. IX-B, Sec. 2(1)", "What does the civil service cover under the 1987 Constitution?", "All branches, subdivisions, instrumentalities and agencies of the Government, including GOCCs with original charters", [("Only national government agencies", "GI-SOUNDS-RIGHT"), ("Only the executive branch", "GI-SOUNDS-RIGHT"), ("All corporations doing business in the Philippines", "GI-SOUNDS-RIGHT")], "embraces all branches, subdivisions, instrumentalities, and agencies of the Government, including government-owned or controlled corporations with original charters", "The civil service is government-wide, including chartered GOCCs."),
 (C, "Art. IX-B, Sec. 2(2)", "Under the 1987 Constitution, appointments in the civil service shall be made only according to what?", "Merit and fitness, determined as far as practicable by competitive examination", [("Seniority alone", "GI-SOUNDS-RIGHT"), ("Recommendation of a local official", "GI-SOUNDS-RIGHT"), ("Length of residence in the area", "GI-SOUNDS-RIGHT")], "according to merit and fitness to be determined, as far as practicable", "Merit and fitness is the constitutional rule."),
 (C, "Art. IX-B, Sec. 2(3)", "Under the 1987 Constitution, can a civil service officer or employee be suspended or dismissed without cause?", "No; only for cause provided by law", [("Yes, at the pleasure of the head of office", "GI-SOUNDS-RIGHT"), ("Yes, after 30 days' notice", "GI-SOUNDS-RIGHT"), ("Only during the first year of service", "GI-SOUNDS-RIGHT")], "No officer or employee of the civil service shall be removed or suspended except for cause provided by law", "Security of tenure: removal only for legal cause."),
 (C, "Art. IX-B, Sec. 2(4)", "Under the 1987 Constitution, may a civil service officer or employee engage in partisan political campaigns?", "No, directly or indirectly", [("Yes, outside office hours", "GI-SOUNDS-RIGHT"), ("Yes, if on leave", "GI-SOUNDS-RIGHT"), ("Only for local elections", "GI-SOUNDS-RIGHT")], "shall engage, directly or indirectly, in any electioneering or partisan political campaign", "Civil servants may not campaign, directly or indirectly."),
 (C, "Art. IX-B, Sec. 2(5)", "Under the 1987 Constitution, the right of government employees to do what shall not be denied?", "Self-organization", [("Strike", "GI-SOUNDS-RIGHT"), ("Campaign for candidates", "GI-SOUNDS-RIGHT"), ("Hold two government posts", "GI-SOUNDS-RIGHT")], "The right to self-organization shall not be denied to government employees", "Employees may form unions (self-organization)."),
 (C, "Art. IX-B, Sec. 6", "Within how long after an election may a losing candidate NOT be appointed to a government office?", "Within one year after the election", [("Within six months after the election", "GI-NEIGHBOR-NUMBER"), ("Within two years after the election", "GI-NEIGHBOR-NUMBER"), ("Within three years after the election", "GI-NEIGHBOR-NUMBER")], "No candidate who has lost in any election, shall within one year after such election", "Losing candidates wait one year before appointment."),
 (C, "Art. IX-B, Sec. 8", "Under the 1987 Constitution, may a public officer accept a title of nobility from a foreign government without the consent of Congress?", "No", [("Yes, if it is honorary", "GI-SOUNDS-RIGHT"), ("Yes, with the President's consent alone", "GI-WRONG-BODY"), ("Yes, after retirement only", "GI-SOUNDS-RIGHT")], "accept without the consent of the Congress, any present, emolument, office, or title of any kind from any foreign government", "Congress must consent to any foreign title, gift or office."),
 (C, "Art. IX-B, Sec. 8", "What does the 1987 Constitution say about double or additional compensation for public officers?", "It is not allowed unless specifically authorized by law", [("It is allowed for overtime work", "GI-SOUNDS-RIGHT"), ("It is allowed if the head of office approves", "GI-WRONG-BODY"), ("It is allowed for elected officials", "GI-SOUNDS-RIGHT")], "No elective or appointive public officer or employee shall receive additional, double, or indirect compensation, unless specifically authorized by law", "Double pay needs a specific law."),
 (C, "Art. IX-C, Sec. 1(1)", "How many members does the Commission on Elections have, counting the Chairman?", "7", [("5", "GI-NEIGHBOR-NUMBER"), ("3", "GI-NEIGHBOR-NUMBER"), ("9", "GI-NEIGHBOR-NUMBER")], "composed of a Chairman and six Commissioners", "COMELEC: a Chairman and six Commissioners."),
 (C, "Art. IX-D, Sec. 1(1)", "How many members does the Commission on Audit have, counting the Chairman?", "3", [("5", "GI-NEIGHBOR-NUMBER"), ("7", "GI-NEIGHBOR-NUMBER"), ("2", "GI-NEIGHBOR-NUMBER")], "composed of a Chairman and two Commissioners", "COA: a Chairman and two Commissioners."),
 (C, "Art. IX-D, Sec. 2(1)", "Which constitutional body examines, audits and settles accounts of government revenues and expenditures?", "Commission on Audit", [("Civil Service Commission", "GI-WRONG-BODY"), ("Department of Budget and Management", "GI-WRONG-BODY"), ("Office of the Ombudsman", "GI-WRONG-BODY")], "The Commission on Audit shall have the power, authority, and duty to examine, audit, and settle all accounts", "COA audits government funds."),
 (C, "Art. IX-A, Sec. 1", "Which are the three Constitutional Commissions under Article IX of the 1987 Constitution?", "Civil Service Commission, Commission on Elections, and Commission on Audit", [("Civil Service Commission, Commission on Human Rights, and Commission on Audit", "GI-SIBLING-TERM"), ("Commission on Elections, Ombudsman, and Commission on Audit", "GI-SIBLING-TERM"), ("Civil Service Commission, Commission on Elections, and Commission on Appointments", "GI-SIBLING-TERM")], "The Constitutional Commissions, which shall be independent, are the Civil Service Commission, the Commission on Elections, and the Commission on Audit", "CSC, COMELEC and COA are the three."),
 (C, "Art. IX-A, Sec. 7", "Within how many days must a Constitutional Commission decide a case after it is submitted for decision?", "60 days", [("30 days", "GI-NEIGHBOR-NUMBER"), ("90 days", "GI-NEIGHBOR-NUMBER"), ("15 days", "GI-NEIGHBOR-NUMBER")], "within sixty days from the date of its submission for decision", "Commissions decide within 60 days of submission."),
 (C, "Art. IX-A, Sec. 7", "Within how many days from receipt of a copy may a decision of a Constitutional Commission be brought to the Supreme Court on certiorari?", "30 days", [("15 days", "GI-NEIGHBOR-NUMBER"), ("60 days", "GI-NEIGHBOR-NUMBER"), ("10 days", "GI-NEIGHBOR-NUMBER")], "within thirty days from receipt of a copy thereof", "The petition to the Supreme Court is due within 30 days."),
 (C, "Art. XI, Sec. 1", "According to the 1987 Constitution, public office is what?", "A public trust", [("A private right", "GI-SOUNDS-RIGHT"), ("A political reward", "GI-SOUNDS-RIGHT"), ("A lifetime privilege", "GI-SOUNDS-RIGHT")], "Public office is a public trust", "Article XI opens: public office is a public trust."),
 (C, "Art. XI, Sec. 3(6)", "Which body has the sole power to try and decide impeachment cases?", "Senate", [("House of Representatives", "GI-WRONG-BODY"), ("Supreme Court", "GI-WRONG-BODY"), ("Sandiganbayan", "GI-WRONG-BODY")], "The Senate shall have the sole power to try and decide all cases of impeachment", "The Senate tries impeachment."),
 (C, "Art. XI, Sec. 3(5)", "How often may impeachment proceedings be initiated against the same official?", "Not more than once within a period of one year", [("Not more than twice a year", "GI-NEIGHBOR-NUMBER"), ("Once every term", "GI-SOUNDS-RIGHT"), ("Once every six months", "GI-NEIGHBOR-NUMBER")], "No impeachment proceedings shall be initiated against the same official more than once within a period of one year", "The one-year bar."),
 (C, "Art. XI, Sec. 3(6)", "What vote of all Senators is needed to convict in an impeachment case?", "Two-thirds", [("Majority", "GI-NEIGHBOR-NUMBER"), ("Three-fourths", "GI-NEIGHBOR-NUMBER"), ("One-third", "GI-NEIGHBOR-NUMBER")], "concurrence of two-thirds of all the Members of the Senate", "Conviction needs two-thirds of all Senators."),
 (C, "Art. XI, Sec. 3(3)", "What vote of all House Members is needed to affirm or override a committee resolution on impeachment?", "At least one-third", [("Majority", "GI-NEIGHBOR-NUMBER"), ("Two-thirds", "GI-NEIGHBOR-NUMBER"), ("Three-fourths", "GI-NEIGHBOR-NUMBER")], "A vote of at least one-third of all the Members of the House shall be necessary", "One-third of the House is enough."),
 (C, "Art. XI, Sec. 2", "Which of these is NOT a ground for impeachment under the 1987 Constitution?", "Poor performance rating", [("Culpable violation of the Constitution", "GI-SIBLING-TERM"), ("Graft and corruption", "GI-SIBLING-TERM"), ("Betrayal of public trust", "GI-SIBLING-TERM")], "culpable violation of the Constitution, treason, bribery, graft and corruption, other high crimes, or betrayal of public trust", "The grounds are listed in Sec. 2; poor performance is not one."),
